            var prSearchOptions = config.prSearchFn ? { prSearchFn: config.prSearchFn } : {};
            pr = gh.findPRForTicket(scm, ticketKey, prSearchOptions);
        }
        if (!pr) {
            console.warn('No open PR found for ticket:', ticketKey);
