function w2Recorder() {
    var calls = [];
    var mocks = {};
    ['move_to_status', 'post_comment', 'add_label', 'remove_label', 'assign_ticket_to', 'update_field', 'update_description',
     'move_to_state', 'add_work_item_comment', 'add_work_item_label', 'remove_work_item_label',
