                    );
                } catch (e) {}
            }
            return false;
        }
        console.log('Found PR candidate #' + pr.number + ' with title: ' + (pr.title || '(no title)'));
        console.log('PR head branch:', pr.head && pr.head.ref ? pr.head.ref : '(missing)');

        // Step 3: PR details
        console.log('Fetching details for PR #' + pr.number + '...');
