/**
 * Tracker-aware comment markup helpers.
 *
 * Post-action templates historically hard-code Jira wiki markup
 * (`h3.`, `{code}`, `*bold*`, `[text|url]`). When the ticket lives on
 * GitHub Issues (key shapes `gh-12`, `owner/repo#12`, `#12`, bare `12` —
 * owned by common/ticketKeyShapes.js) those comments render as noise. These helpers render each construct in
 * the flavor of the ticket's tracker: Jira wiki for Jira keys, Markdown
 * for GitHub keys — with an explicit override via
 * `customParams.commentMarkup` (`'jira' | 'markdown'`, `'github'` is
 * accepted as an alias for `'markdown'`).
 *
 * Usage:
 *   var commentMarkup = require('./common/commentMarkup.js');
 *   var m = commentMarkup.forTicket(ticketKey, customParams);
 *   var comment = m.h(3, 'Development Completed') + '\n\n' +
 *       m.bold('Branch:') + ' ' + m.inline(branchName) + '\n';
 *
 * The Jira flavor output is byte-identical to the historical templates,
 * so Jira-facing behavior is unchanged.
 */
'use strict';

var ticketKeyShapes = require('./ticketKeyShapes.js');

function flavorForTicket(ticketKey, customParams) {
    var explicit = customParams && customParams.commentMarkup;
    if (typeof explicit === 'string' && explicit) {
        var norm = explicit.toLowerCase();
        if (norm === 'markdown' || norm === 'github') return 'markdown';
        if (norm === 'jira') return 'jira';
    }
    // Key shapes come from the single owner (gh-770): common/ticketKeyShapes.js.
    if (ticketKeyShapes.isGitHubKeyShape(ticketKey)) return 'markdown';
    return 'jira';
}

function markdownFlavor() {
    return {
        h: function (level, text) {
            var prefix = '';
            for (var i = 0; i < level; i++) prefix += '#';
            return prefix + ' ' + text;
        },
        bold: function (text) { return '**' + text + '**'; },
        italic: function (text) { return '_' + text + '_'; },
        inline: function (text) { return '`' + text + '`'; },
        code: function (text, lang) {
            return '```' + (lang || '') + '\n' + text + '\n```';
        },
        link: function (text, url) { return '[' + text + '](' + url + ')'; },
        panel: function (title, body, jiraOpts) {
            var header = title ? '> **' + title + '**\n>\n' : '';
            var quoted = String(body).split('\n').map(function (line) {
                return '> ' + line;
            }).join('\n');
            return header + quoted;
        }
    };
}

/**
 * Prepare PR for Review Action (preCliJSAction for pr_review agent)
 * 1. Finds PR associated with the ticket
 * 2. Checks out the PR branch
 * 3. Writes input folder: pr_info.md, pr_diff.txt, pr_discussions.md, pr_discussions_raw.json
 * 4. Posts "Review Started" comment to Jira
 */

var configLoader = require('./configLoader.js');
const gh = require('./common/githubHelpers.js');
const gitOps = require('./common/gitOps.js');
const commentMarkup = require('./common/commentMarkup.js');
const fetchParentContextToInput = require('./fetchParentContextToInput.js');
var trackersModule = require('./common/trackers.js');

function action(params) {
    try {
        const inputFolder = params.inputFolderPath;
        const ticketKey = inputFolder.split('/').pop();
        // PR-anchored review (issue #687): a `pr-N` contextId makes the PR
        // itself the anchor — no ticket lookup, no ticket comments. Covers
        // PRs born without an issue and on-demand PR reviews (agent:review).
        var jp = params.jobParams || params;
        var anchorMatch = /^pr-(\d+)$/.exec(String(ticketKey || ''));
        const prAnchor = (anchorMatch ? parseInt(anchorMatch[1], 10) : null) ||
            (parseInt(jp.prNumber || jp.pr || '', 10) || null);
        const noTicket = !!prAnchor;
        var config = configLoader.loadProjectConfig(params.jobParams || params);
        var scm = configLoader.createScm(config);
        var tracker = trackersModule.createTracker(config, (params.jobParams && params.jobParams.customParams) || params.customParams || {});

        console.log('=== Preparing PR for review:', ticketKey, '===');
        console.log('Input folder:', inputFolder);
        console.log('Configured repository:', config.repository && config.repository.owner && config.repository.repo
            ? config.repository.owner + '/' + config.repository.repo
            : '(fallback to git remote)');
        console.log('Configured working directory:', config.workingDir || '(not set)');
        console.log('Configured base branch:', config.git && config.git.baseBranch ? config.git.baseBranch : '(not set)');

        // Step 1: GitHub repo info — prefer targetRepository from config over git remote
        var repoInfo = null;
        if (config.repository && config.repository.owner && config.repository.repo) {
            repoInfo = { owner: config.repository.owner, repo: config.repository.repo };
            console.log('Using targetRepository from config:', repoInfo.owner + '/' + repoInfo.repo);
        } else {
            console.log('Target repository not configured, resolving from git remote...');
            repoInfo = scm.getRemoteRepoInfo();
        }
        if (!repoInfo) {
            const err = 'Could not determine GitHub repository from git remote';
            console.error('PR review setup failed at repository resolution:', err);
