            pr = gh.findPRForTicket(scm, ticketKey, prSearchOptions);
        }
        if (!pr) {
            console.warn('No open PR found for ticket:', ticketKey);
            if (!noTicket) {
                try {
                    tracker.postComment(ticketKey,
                        commentMarkup.forTicket(ticketKey).h(3, '⚠️ PR Review Setup Failed') + '\n\n' +
