}

function buildDetailsFailureComment(prNumber) {
    return commentMarkup.forTicket(ticketKeyForDetails(prNumber)).h(3, '⚠️ PR Review Setup Failed') +
        '\n\nCould not fetch details for PR #' + prNumber + '.\n\n_Review cancelled._';
}

function ticketKeyForDetails(prNumber) {
    return prNumber; // placeholder — flavor is decided by the caller's ticket key
}

/**
 * Posts a failure comment unless it is null (PR-anchored runs have no ticket
 * to notify). Tracker errors are swallowed — failure reporting must never
