    if (prDetails) {
        console.log('Loaded PR details for #' + prDetails.number +
            ' | head=' + refLabel(prDetails.head) +
            ' | base=' + refLabel(prDetails.base) +
            ' | changed_files=' + (prDetails.changed_files || 0));
        return { prDetails: prDetails };
