            record.ghCalls.push({ fn: 'fetchDiscussionsAndRawData', prNumber: prNumber });
            return opts.discussions !== undefined ? opts.discussions :
                { markdown: '# PR Discussion History', rawThreads: [{ index: 1, body: 'x' }] };
        },
